// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, "", ""); }
    function testFuzz_property(address from, address to, uint256 value) public {
        vm.assume(from != address(0) && to != address(0));
        vm.assume(from != to);
        c.mintToken(from, value);
        vm.prank(from);
        bool success = c.transfer(to, value);
        assertTrue(success == true || c.frozenAccount(from) || c.frozenAccount(to));
    }
}

